// Hybrid: the page plays a recording as pure CSS (generated by recording.py),
// and loads the real VM only when the user interacts.
//
// Initial page load: no JavaScript. The first focus of the terminal input loads
// this bundle (see the inline onfocus handler), which loads xterm +
// recording.json to take over the recording. On typing: libv86.js + v86.wasm
// (~300 KB) + fs.json (~1.4 MB) + snapshot.bin.gz (~16 MB, inflated
// client-side) are fetched, then the VM resumes at a live shell prompt.
//
// State machine:
//   'recording' - replaying recording.json into xterm
//   'waiting'   - recording done, fake prompt shown, collecting typed input
//                 (VM may be preloading in background from the first keypress)
//   'live'      - real VM running, all input forwarded to serial

// Directory of bundle.js, so asset fetches resolve wherever it is served from.
var BASE = document.currentScript.src.replace(/[^/]*$/, '');

var mode = 'recording';
var term = null;
var emulator = null;
var stopReplay = null;
var pendingCmd = '';
var vmPreloading = false; // fetch + V86 init started
var vmReady = false;      // emulator-ready fired, VM can receive input
var pendingLive = null;   // fn(): drive the shell once live, queued while VM loads
var pendingLiveTimer = null; // setTimeout ID for the emulator-ready settle delay
var recText = '';         // text written to terminal so far during recording
var gate = null;          // {buf, marker, onDone, timer}: suppress VM output during
                          // a hidden round-trip (e.g. the stty window-size sync)

var statusEl = document.getElementById('status-left');
function setStatus(html) {
  if (statusEl) statusEl.innerHTML = html;
}

// Track all in-flight terminal network requests and show a loading indicator.
// Safe to patch here: every fetch/XHR from this point is terminal-related
// (recording.json, snapshot.bin, v86.wasm, fs.json, 9p content blobs).
// xterm.js and libv86.js load via script tags and are not tracked.
// v86's 9p filesystem uses XHR (not fetch), so both APIs need patching.
// Only show for real network fetches: cache hits complete in <5ms so a 50ms
// timer ensures we never show the indicator for already-cached resources.
var _netCount = 0;
var _netClearTimer = null;
function _netShow() {
  if (++_netCount === 1) {
    if (_netClearTimer) { clearTimeout(_netClearTimer); _netClearTimer = null; }
    setStatus('Loading…');
  }
}
function _netHide() {
  if (--_netCount === 0)
    _netClearTimer = setTimeout(function() { _netClearTimer = null; setStatus(''); }, 200);
}
function _trackRequest() {
  var t = setTimeout(function() { t = null; _netShow(); }, 50);
  return function() { if (t) { clearTimeout(t); t = null; } else { _netHide(); } };
}

var _origFetch = window.fetch;
window.fetch = function() {
  var done = _trackRequest();
  return _origFetch.apply(this, arguments).finally(done);
};

var _origXHROpen = XMLHttpRequest.prototype.open;
XMLHttpRequest.prototype.open = function() {
  var done = _trackRequest();
  this.addEventListener('loadend', done);
  return _origXHROpen.apply(this, arguments);
};

function loadInto(el) {
  return new Promise(function(resolve, reject) {
    el.onload = resolve;
    el.onerror = function() { reject(new Error('failed to load ' + (el.src || el.href))); };
    document.head.appendChild(el);
  });
}
function loadScript(src) {
  var s = document.createElement('script');
  s.src = src;
  return loadInto(s);
}
function loadStyle(href) {
  var l = document.createElement('link');
  l.rel = 'stylesheet';
  l.href = href;
  return loadInto(l);
}

var termContainer = document.getElementById('terminal');

// --- Terminal (xterm) ---
// Takes over from the CSS recording, continuing it where it is.
var terminalLoading = null;
function ensureTerminal() {
  if (!terminalLoading) {
    var recording = fetch(BASE + 'recording.json')
      .then(function(r) { return r.json(); })
      .catch(function() { return null; });
    terminalLoading = Promise.all([recording, loadStyle(BASE + 'xterm.css'), loadScript(BASE + 'xterm.js')])
      .then(function(results) {
        var segs = results[0];
        var elapsed = recordingElapsed(); // before the CSS recording is removed
        term = new window.Terminal({
          scrollback: 1000,
          fontFamily: '"Courier New", monospace',
          fontSize: 14,
          theme: { background: '#000000', foreground: '#cccccc' },
          cursorBlink: true,
          convertEol: false,
        });
        document.getElementById('recording').remove();
        term.open(termContainer);
        fitTerminal();
        term.onData(onInput);
        if (segs) stopReplay = playRecording(segs, elapsed, onRecordingEnd);
        else enterLive(function() {});
        // Hand focus to xterm, except on touch devices (see proxyInput).
        if (document.activeElement !== proxyInput) proxyInput.remove();
        else if (touch) proxyInput.style.pointerEvents = 'none';
        else term.focus(); // blurs proxyInput, which then removes itself
        var resizeTimer = null;
        window.addEventListener('resize', function() {
          if (resizeTimer) clearTimeout(resizeTimer);
          resizeTimer = setTimeout(fitTerminal, 150);
        });
      })
      .catch(function(e) {
        console.error('Terminal load failed:', e);
        setStatus('Failed to load the terminal — please refresh');
      });
  }
  return terminalLoading;
}

// --- Input before xterm ---
// The invisible textarea over the recording (in the page's HTML) takes the
// first tap or key, so phones open their keyboard right away (focus must happen
// within the tap). Its input is translated to what xterm's onData would deliver
// and queued until xterm is ready. On touch devices it then stays focused and
// keeps forwarding, as moving focus outside a tap can close the keyboard;
// elsewhere xterm takes over focus.
var proxyInput = document.getElementById('terminal-input');
var touch = matchMedia('(pointer: coarse)').matches;

var KEYS = {
  Enter: '\r', Backspace: '\x7f', Tab: '\t', Escape: '\x1b',
  ArrowUp: '\x1b[A', ArrowDown: '\x1b[B', ArrowRight: '\x1b[C', ArrowLeft: '\x1b[D',
};
function keyData(e) {
  if (e.ctrlKey && e.key.toLowerCase() === 'c') return '\x03';
  if (e.ctrlKey || e.metaKey || e.altKey) return null;
  return KEYS[e.key] || (e.key.length === 1 ? e.key : null);
}

var queuedInput = [];
function proxyEmit(data) {
  if (term) { onInput(data); return; }
  queuedInput.push(data);
  ensureTerminal().then(function() {
    if (term) queuedInput.splice(0).forEach(onInput);
  });
}
proxyInput.addEventListener('blur', function() { if (term) proxyInput.remove(); });
proxyInput.addEventListener('keydown', function(e) {
  var data = keyData(e);
  if (data === null) return; // e.g. phone keyboards: arrives as an input event
  e.preventDefault();
  proxyEmit(data);
});
// Phone keyboards may compose words; only the finished text is sent.
proxyInput.addEventListener('compositionend', function(e) {
  if (e.data) e.data.split('').forEach(proxyEmit);
  proxyInput.value = '';
});
proxyInput.addEventListener('input', function(e) {
  if (e.isComposing || e.inputType === 'insertCompositionText') return;
  if (e.inputType === 'insertLineBreak') proxyEmit('\r');
  else if (e.inputType === 'deleteContentBackward') proxyEmit('\x7f');
  else proxyInput.value.split('').forEach(proxyEmit); // typed or pasted text
  proxyInput.value = '';
});

// --- Responsive sizing ---
// The font is fixed, so the cell size is constant and cols/rows follow the
// container's pixel size (which is CSS-responsive to the viewport).
function cellSize() {
  var d = term._core && term._core._renderService && term._core._renderService.dimensions;
  if (!d) return null;
  var cw = d.actualCellWidth  || (d.css && d.css.cell && d.css.cell.width);
  var ch = d.actualCellHeight || (d.css && d.css.cell && d.css.cell.height);
  return (cw && ch) ? { cw: cw, ch: ch } : null;
}
function fitTerminal() {
  var cs = cellSize();
  if (!cs) return;
  var cols = Math.max(20, Math.floor(termContainer.clientWidth  / cs.cw));
  var rows = Math.max(6,  Math.floor(termContainer.clientHeight / cs.ch));
  if (cols === term.cols && rows === term.rows) return;
  term.resize(cols, rows);
}

// Suppress VM serial output until `marker` appears, then discard the buffered
// bytes and call onDone. A timeout flushes the buffer if the marker never comes
// so output is never permanently swallowed.
function takeGate() {
  var g = gate; gate = null;
  if (g && g.timer) clearTimeout(g.timer);
  return g;
}
function flushGate() { if (gate) term.write(takeGate().buf); }
function gateOutput(marker, onDone, timeout) {
  flushGate();
  gate = { buf: '', marker: marker, onDone: onDone, timer: null };
  gate.timer = setTimeout(flushGate, timeout || 1500);
}
var winsizeCmd = function() { return 'stty rows ' + term.rows + ' cols ' + term.cols; };

// First transition to live: set the size AND `exec` a fresh login shell. This
// hands the user a clean line editor (arrow keys / history work from the start)
// whose in-memory history is reloaded from /root/.ash_history. busybox's
// `history` builtin can't clear in-memory history, and the snapshot's shell has
// the RAM-zeroing command in it, so respawning is the only way to drop it. tty
// winsize lives on the device, so it survives the exec. $SHELL is busybox
// (exported by the guest init) — NOT /bin/sh, which is bash and prints a
// different prompt that would never match the gate marker below.
//
// busybox appends this whole line to history before running it. HISTFILE=/dev/null
// makes the exiting shell discard its history so our .ash_history write survives.
// The new shell gets HISTFILE=/root/.ash_history via per-command env so it reads
// the "nix run" entry we wrote.
//
// Two-stage gate: LIVE_SYNC (\x01\x02\x03) fires first — these bytes are emitted
// by printf so they can't appear in the command echo, avoiding a race where V86's
// serial FIFO delivers the snapshot shell's buffered "~ # " after the gate is set
// and fires it early. Then we gate on "~ # " from the new shell so onDone fires
// at the right moment for apply() to overlay the prompt correctly.
var LIVE_SYNC = '\x01\x02\x03';
function goLivePrompt(onDone) {
  fitTerminal();
  gateOutput(LIVE_SYNC, function() {
    gateOutput('~ # ', onDone, 8000);
  }, 8000);
  emulator.serial0_send(
    'export LINES=' + term.rows + ' COLUMNS=' + term.cols + '; ' +
    winsizeCmd() + "; printf 'nix run\\n' > /root/.ash_history" +
    "; export HISTFILE=/dev/null; printf '\\001\\002\\003'; HISTFILE=/root/.ash_history exec \"$SHELL\" --login\n"
  );
}

// Go live exactly once (respawning a fresh, sized busybox shell), then run
// apply() to drive it. Queued if the VM is still loading. The 200ms settle
// gives restore_state's serial line a beat before we type into it.
function enterLive(apply) {
  if (mode === 'live') { apply(); return; }
  var go = function() { goLivePrompt(function() { mode = 'live'; setStatus(''); apply(); }); };
  if (vmReady) { go(); return; }
  pendingLive = function() { pendingLiveTimer = setTimeout(function() { pendingLiveTimer = null; go(); }, 200); };
  preloadVM();
}
function cancelPendingLive() {
  pendingLive = null;
  if (pendingLiveTimer) { clearTimeout(pendingLiveTimer); pendingLiveTimer = null; }
}

// Single input pipeline. xterm does not local-echo, so every keystroke arrives
// here (already decoded to bytes/text) and nothing reaches the terminal or VM
// unless we act on it. Routing ALL input through one onData handler — rather
// than also using attachCustomKeyEventHandler — is deliberate: the previous
// two-path design leaked the triggering key's keypress event into the VM the
// instant `mode` flipped to 'live', replaying typed input and running the first
// command twice. One pipeline, one mode check, no leak.
function onInput(data) {
  if (gate) return; // mid window-size sync: ignore input until the shell settles
  if (mode === 'live') { emulator.serial0_send(data); return; }

  // Ctrl+C (ETX) in any pre-live mode: abort the recording, or commit to live.
  if (data === '\x03') {
    if (stopReplay) { stopReplay(); stopReplay = null; }
    if (mode === 'recording') {
      term.write(synthKill());
      mode = 'waiting';
      setStatus('');
      preloadVM();
    } else {
      // waiting: drop pending input and switch to a fresh live prompt.
      pendingCmd = '';
      cancelPendingLive();
      enterLive(function() {});
    }
    return;
  }

  if (mode === 'recording') return; // ignore all other input during playback

  // Escape sequences (arrow keys, Home/End, …) need real line editing, which
  // only the live shell can do. With nothing typed yet, go live and forward the
  // key: e.g. Up recalls "nix run" from the reloaded history. (Mid-line nav is
  // dropped rather than faked.)
  if (data.charCodeAt(0) === 0x1b) {
    if (pendingCmd === '') enterLive(function() { emulator.serial0_send(data); });
    return;
  }

  // waiting: collect a command line, echoing manually. onData may deliver
  // several characters at once (e.g. a paste), so walk the chunk.
  for (var k = 0; k < data.length; k++) {
    var ch = data[k];
    if (ch === '\r' || ch === '\n' || ch === '\t') {
      var cmd = pendingCmd, suffix = ch === '\t' ? '\t' : '\n';
      pendingCmd = '';
      // Erase our echo, reprint the prompt so the shell's own echo redraws it.
      enterLive(function() {
        if (cmd) term.write('\r' + ' '.repeat(4 + cmd.length) + '\r~ # ');
        emulator.serial0_send(cmd + suffix);
      });
      return; // mode may now be live; don't reprocess the rest of the chunk
    }
    if (ch === '\x7f' || ch === '\b') { // DEL / Backspace
      if (pendingCmd.length > 0) { pendingCmd = pendingCmd.slice(0, -1); term.write('\b \b'); }
      continue;
    }
    if (ch >= ' ') { // printable: start preloading on first char, then echo
      if (pendingCmd.length === 0) preloadVM();
      pendingCmd += ch;
      term.write(ch);
    }
  }
}

// --- Recording playback ---
// How long the CSS recording has played: its clock is the start of the final
// cursor's (infinite, so always present) blink animation.
function recordingElapsed() {
  var cursor = document.querySelector('#recording .cursor:not(.erased)');
  var animation = cursor && cursor.getAnimations()[0];
  return animation ? document.timeline.currentTime - animation.startTime : 0;
}
// Writes what has already been shown at once, then plays the rest in time.
function playRecording(segs, elapsed, onDone) {
  var at = 0, timers = [];
  function atTime(fn) {
    if (at <= elapsed) fn();
    else timers.push(setTimeout(fn, at - elapsed));
  }
  segs.forEach(function(seg) {
    at += seg.d;
    atTime(function() {
      var raw = atob(seg.b);
      recText += raw;
      term.write(raw);
    });
  });
  atTime(onDone);
  return function() { timers.forEach(clearTimeout); };
}

// Returns synthetic ^C output to inject when the user interrupts the recording.
// needsCleanup: topology was set up but cleanup hasn't run yet.
function synthKill() {
  var needsCleanup = recText.indexOf('testbed| network topology set up') !== -1 &&
                     recText.indexOf('testbed| cleaning up') === -1;
  if (!needsCleanup) return '~ # ';
  var pidMatch = recText.match(/client\| main \(PID (\d+)\) started/);
  var killed = pidMatch ? 'testbed| PID ' + pidMatch[1] + ' killed\r\n' : '';
  return '^C\r\n' + killed + 'testbed| cleaning up...\r\n~ # ';
}

function onRecordingEnd() {
  mode = 'waiting';
  setStatus('');
}

var CMDLINE = [
  'root=host9p rootfstype=9p rootflags=trans=virtio,cache=loose rw',
  'init=/init console=ttyS0,115200 noapic nolapic',
  'loglevel=1 nokaslr mce=off',
  'mitigations=off audit=0 random.trust_cpu=on',
].join(' ');

// Start fetching the snapshot and initialising V86 in the background.
// Called on the user's first keypress so the VM is likely ready by Enter/Tab.
// The snapshot ships gzip-compressed and is inflated here: static hosts (e.g.
// GitHub Pages) serve files verbatim, with no Content-Encoding negotiation.
// Any snapshot failure (missing file, old browser) falls back to a fresh boot.
function preloadVM() {
  if (vmPreloading || vmReady || mode === 'live') return;
  vmPreloading = true;

  var snapshot = fetch(BASE + 'snapshot.bin.gz')
    .then(function(r) {
      if (!r.ok) return null;
      return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
    })
    .catch(function() { return null; });

  Promise.all([snapshot, loadScript(BASE + 'libv86.js')])
    .then(function(results) {
      var buf = results[0];
      var vmState = null;
      if (buf) {
        var stateLen = new DataView(buf).getUint32(0, true);
        vmState = buf.slice(4, 4 + stateLen);
      }
      var cfg = {
        wasm_path: BASE + 'v86.wasm',
        memory_size: 256 * 1024 * 1024,
        filesystem: { baseurl: BASE + 'base/', basefs: { url: BASE + 'fs.json' } },
        net_device: { type: 'virtio' },
        preserve_mac_from_state_image: true,
        disable_speaker: true,
        cmdline: CMDLINE,
      };
      if (!vmState) {
        cfg.bios = { url: BASE + 'bios.bin' };
        cfg.bzimage = { url: BASE + 'bzImage' };
        cfg.autostart = true;
      }
      emulator = new V86(cfg);
      emulator.add_listener('emulator-ready', function() {
        emulator.add_listener('serial0-output-byte', function(byte) {
          if (gate) {
            gate.buf += String.fromCharCode(byte);
            if (gate.buf.indexOf(gate.marker) !== -1) takeGate().onDone();
            return;
          }
          term.write(new Uint8Array([byte]));
        });
        if (vmState) {
          emulator.restore_state(vmState);
          emulator.run();
        } else {
          emulator.run();
          term.write('Booting…\r\n');
        }
        vmReady = true;
        // Run whatever the user queued while the VM loaded (Enter, Tab, an arrow
        // key…). If nothing's queued they're still typing — wait for it.
        if (pendingLive) { var p = pendingLive; pendingLive = null; p(); }
      });
    })
    .catch(function(e) {
      console.error('VM load failed:', e);
      vmPreloading = false;
      setStatus('Failed to connect — please refresh');
    });
}

// Loaded on the first focus of the input: take over what was typed meanwhile.
proxyInput.value.replace(/\n/g, '\r').split('').forEach(proxyEmit);
proxyInput.value = '';
ensureTerminal();
